    override fun fetchCandidates(shape: String, filter: QF): List<Row> {
        if (shape == "GreenhouseTrial")
            questions.treatedTrialCandidates.match(filter)?.let { h -> return store.treatedTrialCandidates().map { it.toRow() } }
        if (shape == "GreenhouseTrial")
            questions.evaluatedTrialCandidates.match(filter)?.let { h -> return store.evaluatedTrialCandidates().map { it.toRow() } }
        if (shape == "Peptide")
            questions.greenhouseValidatedCandidates.match(filter)?.let { h -> return store.greenhouseValidatedCandidates().map { it.toRow() } }
        if (shape == "PlotObservation")
            questions.lockedObservationCandidates.match(filter)?.let { h -> return store.lockedObservationCandidates().map { it.toRow() } }
        if (shape == "GreenhousePlot")
            questions.treatedPlotCandidates.match(filter)?.let { h -> return store.treatedPlotCandidates().map { it.toRow() } }
        if (shape == "GreenhouseTrial")
            questions.activeTrialCandidates.match(filter)?.let { h -> return store.activeTrialCandidates().map { it.toRow() } }
        if (shape == "Greenhouse")
            questions.outOfBandCandidates.match(filter)?.let { h -> return store.outOfBandCandidates().map { it.toRow() } }
        if (shape == "ClimateExcursion")
            questions.openExcursionCandidates.match(filter)?.let { h -> return store.openExcursionCandidates().map { it.toRow() } }
        if (shape == "FieldTrial")
            questions.permittedTrialCandidates.match(filter)?.let { h -> return store.permittedTrialCandidates(h.date(0), h.date(1)).map { it.toRow() } }
        if (shape == "FieldTrial")
            questions.plantedTrialCandidates.match(filter)?.let { h -> return store.plantedTrialCandidates().map { it.toRow() } }
        if (shape == "FieldTrial")
            questions.harvestedTrialCandidates.match(filter)?.let { h -> return store.harvestedTrialCandidates().map { it.toRow() } }
        if (shape == "CollectionTask")
            questions.overdueTaskCandidates.match(filter)?.let { h -> return store.overdueTaskCandidates(h.date(0)).map { it.toRow() } }
        if (shape == "LabExperiment")
            questions.recordLabHitCandidates.match(filter)?.let { h -> return store.recordLabHitCandidates().map { it.toRow() } }
        if (shape == "Greenhouse")
            questions.openClimateExcursionCandidates.match(filter)?.let { h -> return store.openClimateExcursionCandidates().map { it.toRow() } }
        if (shape == "Greenhouse")
            questions.raiseSensorAlertCandidates.match(filter)?.let { h -> return store.raiseSensorAlertCandidates(h.instant(0)).map { it.toRow() } }
        if (shape == "TreatmentApplication")
            questions.noticeWashOffCandidates.match(filter)?.let { h -> return store.noticeWashOffCandidates().map { it.toRow() } }
        if (shape == "FieldTrial")
            questions.noticeHaltCandidates.match(filter)?.let { h -> return store.noticeHaltCandidates().map { it.toRow() } }
        if (shape == "CollectionTask")
            questions.remindTaskCandidates.match(filter)?.let { h -> return store.remindTaskCandidates(h.date(0), h.date(1)).map { it.toRow() } }
        if (shape == "Peptide")
            questions.never1Candidates.match(filter)?.let { h -> return store.never1Candidates().map { it.toRow() } }
        if (shape == "AssayReading")
            questions.never2Candidates.match(filter)?.let { h -> return store.never2Candidates().map { it.toRow() } }
        if (shape == "AssayReading")
            questions.never3Candidates.match(filter)?.let { h -> return store.never3Candidates().map { it.toRow() } }
        if (shape == "GreenhousePlot")
            questions.never5Candidates.match(filter)?.let { h -> return store.never5Candidates().map { it.toRow() } }
        if (shape == "PlotObservation")
            questions.never7Candidates.match(filter)?.let { h -> return store.never7Candidates().map { it.toRow() } }
        if (shape == "PlotObservation")
            questions.never8Candidates.match(filter)?.let { h -> return store.never8Candidates().map { it.toRow() } }
        if (shape == "PlotObservation")
            questions.never10Candidates.match(filter)?.let { h -> return store.never10Candidates().map { it.toRow() } }
        if (shape == "FieldPlot")
            questions.never14Candidates.match(filter)?.let { h -> return store.never14Candidates().map { it.toRow() } }
        if (shape == "Scouting")
            questions.never15Candidates.match(filter)?.let { h -> return store.never15Candidates().map { it.toRow() } }
        if (shape == "Scouting")
            questions.never16Candidates.match(filter)?.let { h -> return store.never16Candidates().map { it.toRow() } }
        if (shape == "Harvest")
            questions.never18Candidates.match(filter)?.let { h -> return store.never18Candidates().map { it.toRow() } }
        if (shape == "PhytotoxicityReport")
            questions.never19Candidates.match(filter)?.let { h -> return store.never19Candidates().map { it.toRow() } }
        if (shape == "CollectionTask")
            questions.never21Candidates.match(filter)?.let { h -> return store.never21Candidates().map { it.toRow() } }
        return fetchAll(shape) // unrecognized filters fall back to the scan floor
    }

