private fun List<QConst>.date(i: Int): LocalDate = (this[i] as QConst.QDate).v
private fun List<QConst>.instant(i: Int): Instant = (this[i] as QConst.QDateTime).v

// ── row mappers: the generic wire format <-> the typed rows ──

fun Row.toCropRow(): CropRow = CropRow(
    key = key,
    name = fields["name"] as String,
)

fun CropRow.toRow(): Row = Row("Crop", key, buildMap {
    put("name", name)
})

fun Row.toPathogenRow(): PathogenRow = PathogenRow(
    key = key,
    name = fields["name"] as String,
    host = fields["host"] as Ref.Persisted,
)

fun PathogenRow.toRow(): Row = Row("Pathogen", key, buildMap {
    put("name", name)
    put("host", host)
})

fun Row.toPeptideRow(): PeptideRow = PeptideRow(
    key = key,
    code = fields["code"] as String,
    sequence = fields["sequence"] as String,
)

fun PeptideRow.toRow(): Row = Row("Peptide", key, buildMap {
    put("code", code)
    put("sequence", sequence)
})

fun Row.toAssayProtocolRow(): AssayProtocolRow = AssayProtocolRow(
    key = key,
    name = fields["name"] as String,
    durationHours = (fields["durationHours"] as Number).toInt(),
    replicates = (fields["replicates"] as Number).toInt(),
    hitThreshold = fields["hitThreshold"] as BigDecimal,
)

fun AssayProtocolRow.toRow(): Row = Row("AssayProtocol", key, buildMap {
    put("name", name)
    put("durationHours", durationHours)
    put("replicates", replicates)
    put("hitThreshold", hitThreshold)
})

fun Row.toLabExperimentRow(): LabExperimentRow = LabExperimentRow(
    key = key,
    peptide = fields["peptide"] as Ref.Persisted,
    pathogen = fields["pathogen"] as Ref.Persisted,
    protocol = fields["protocol"] as Ref.Persisted,
)

fun LabExperimentRow.toRow(): Row = Row("LabExperiment", key, buildMap {
    put("peptide", peptide)
    put("pathogen", pathogen)
    put("protocol", protocol)
})

fun Row.toAssayRow(): AssayRow = AssayRow(
    key = key,
    experiment = fields["experiment"] as Ref.Persisted,
    replicate = (fields["replicate"] as Number).toInt(),
)

fun AssayRow.toRow(): Row = Row("Assay", key, buildMap {
    put("experiment", experiment)
    put("replicate", replicate)
})

fun Row.toAssayReadingRow(): AssayReadingRow = AssayReadingRow(
    key = key,
    assay = fields["assay"] as Ref.Persisted,
    hoursElapsed = (fields["hoursElapsed"] as Number).toInt(),
    inhibitionPercent = fields["inhibitionPercent"] as BigDecimal,
)

fun AssayReadingRow.toRow(): Row = Row("AssayReading", key, buildMap {
    put("assay", assay)
    put("hoursElapsed", hoursElapsed)
    put("inhibitionPercent", inhibitionPercent)
})

fun Row.toLabHitRow(): LabHitRow = LabHitRow(
    key = key,
    experiment = fields["experiment"] as Ref.Persisted,
    meanPeakInhibition = fields["meanPeakInhibition"] as BigDecimal,
    recordedOn = fields["recordedOn"] as Instant,
)

fun LabHitRow.toRow(): Row = Row("LabHit", key, buildMap {
    put("experiment", experiment)
    put("meanPeakInhibition", meanPeakInhibition)
    put("recordedOn", recordedOn)
})

fun Row.toLabHitRetractionRow(): LabHitRetractionRow = LabHitRetractionRow(
    key = key,
    experiment = fields["experiment"] as Ref.Persisted,
